import{_ as a,o as t,c as r,ag as i}from"./chunks/framework.D7xI0JV8.js";const u=JSON.parse('{"title":"AEGIS-1 (GATE Standard Context)","description":"","frontmatter":{},"headers":[],"relativePath":"aegis.md","filePath":"aegis.md"}'),o={name:"aegis.md"};function s(l,e,n,c,d,h){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="aegis-1-gate-standard-context" tabindex="-1">AEGIS-1 (GATE Standard Context) <a class="header-anchor" href="#aegis-1-gate-standard-context" aria-label="Permalink to &quot;AEGIS-1 (GATE Standard Context)&quot;">​</a></h1><p>AEGIS-1 is the standards-facing frame for GATE-style autonomous execution semantics used in the zkde.fi ecosystem narrative.</p><h2 id="the-problem-this-solves" tabindex="-1">The Problem This Solves <a class="header-anchor" href="#the-problem-this-solves" aria-label="Permalink to &quot;The Problem This Solves&quot;">​</a></h2><p>Without a shared execution language, integrators describe delegation, policy checks, and proof artifacts differently, making cross-system interoperability difficult.</p><h2 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h2><p>A common framing helps external builders map their systems to zkde.fi semantics while preserving flexibility in product-specific flow behavior.</p><h2 id="core-aegis-gate-concepts" tabindex="-1">Core AEGIS/GATE Concepts <a class="header-anchor" href="#core-aegis-gate-concepts" aria-label="Permalink to &quot;Core AEGIS/GATE Concepts&quot;">​</a></h2><ul><li>constrained delegation</li><li>policy-aware execution</li><li>verification artifact lifecycle</li><li>receipt and attestation traceability</li></ul><h2 id="conceptual-standard-flow" tabindex="-1">Conceptual Standard Flow <a class="header-anchor" href="#conceptual-standard-flow" aria-label="Permalink to &quot;Conceptual Standard Flow&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20D%5BDelegation%5D%20--%3E%20P%5BPolicy%20context%5D%0A%20%20P%20--%3E%20V%5BVerification%20path%5D%0A%20%20V%20--%3E%20E%5BExecution%5D%0A%20%20E%20--%3E%20R%5BReceipts%20and%20attestations%5D">flowchart LR
  D[Delegation] --&gt; P[Policy context]
  P --&gt; V[Verification path]
  V --&gt; E[Execution]
  E --&gt; R[Receipts and attestations]</pre><h2 id="problem-it-solves-for-integrators" tabindex="-1">Problem It Solves For Integrators <a class="header-anchor" href="#problem-it-solves-for-integrators" aria-label="Permalink to &quot;Problem It Solves For Integrators&quot;">​</a></h2><p>Provides a vocabulary to design:</p><ul><li>compatible automation controllers</li><li>route-aware policy engines</li><li>verifier-facing reporting and audit views</li></ul><h2 id="why-it-matters-for-product-teams" tabindex="-1">Why It Matters For Product Teams <a class="header-anchor" href="#why-it-matters-for-product-teams" aria-label="Permalink to &quot;Why It Matters For Product Teams&quot;">​</a></h2><p>A standards frame is useful only when grounded in real product behavior. In zkde.fi, operational docs remain source of truth for route-specific semantics and API contracts.</p><h2 id="practical-use" tabindex="-1">Practical Use <a class="header-anchor" href="#practical-use" aria-label="Permalink to &quot;Practical Use&quot;">​</a></h2><p>Use AEGIS/GATE framing as an integration design layer, then validate concrete behavior with:</p><ul><li><a href="/docs/api-overview.html">API overview</a></li><li><a href="/docs/architecture-summary.html">Architecture summary</a></li><li><a href="/docs/developers.html">Developers</a></li></ul><p>Next: <a href="/docs/developers.html">Developers</a> | <a href="/docs/api-overview.html">API overview</a></p>`,19)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
